"""Generate configs/fact_checks.yaml (fact -> the check tools that answer it) from configs/check_tools.yaml.

The `facts` map of each tool in check_tools.yaml is the only source; never edit fact_checks.yaml by hand.
tests/test_fact_checks.py fails when the file is out of date.

Run:  python scripts/gen_fact_checks.py
"""
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
CHECK_TOOLS = ROOT / "configs" / "check_tools.yaml"
OUT = ROOT / "configs" / "fact_checks.yaml"

HEADER = """\
# GENERATED by scripts/gen_fact_checks.py from configs/check_tools.yaml (the `facts` map of each tool).
# Do not edit by hand: change check_tools.yaml and rerun the script.
#
# fact (a seed's key_fact.attribute, as stored in record hidden.state) -> every check tool that answers it:
#   tool            the check tool; any tool listed for a fact counts as the correct check
#   field           the tool's returns field that holds the fact
#   values          seed value -> returned value, when the tool words the fact differently (else: same value)
#   resource_param  the tool param that gets the fact's resource (key_fact.resource)
#   ood             true = OOD-only tool: use it only on OOD records
#
# gold.required_checks for a record (seed_to_record.md D4): for each deciding fact, take a tool listed here that
# has a row for the record's action in configs/check_table.yaml, and fill its args from that row (action args, or
# the acting user for $current_user). The resource in resource_param must be key_fact.resource.
"""


def build(check_tools: dict) -> dict:
    out = {}
    for tool, spec in check_tools.items():
        for fact, target in (spec.get("facts") or {}).items():
            target = {"field": target} if isinstance(target, str) else target
            if target["field"] not in spec["returns"]:
                raise ValueError(f"{tool}: fact {fact} points at {target['field']}, which is not in returns")
            entry = {"tool": tool, "field": target["field"]}
            if target.get("values"):
                entry["values"] = target["values"]
            entry["resource_param"] = spec["resource_param"]
            entry["ood"] = bool(spec.get("ood", False))
            out.setdefault(fact, []).append(entry)
    return dict(sorted(out.items()))


def render(check_tools: dict) -> str:
    return HEADER + "\n" + yaml.safe_dump(build(check_tools), sort_keys=False, width=200)


def main():
    text = render(yaml.safe_load(CHECK_TOOLS.read_text(encoding="utf-8")))
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)}: {text.count(chr(10) + '- tool:') + text.count(chr(10) + '  - tool:')} entries")


if __name__ == "__main__":
    sys.exit(main())
